-- Brief sleep between bind retries (nanosleep if available).
local function brief_sleep_ms(ms)
    ms = ms or 200
    if syscall.nanosleep then
        local ts = malloc(16)
        write64(ts, 0)                          -- tv_sec
        write64(ts + 8, ms * 1000000)           -- tv_nsec
        pcall(function() syscall.nanosleep(ts, 0) end)
    end
end

-- FTP listen sockets (SO_REUSEADDR/PORT so a second inject can re-bind after cleanup)
local function open_listen(port, name)
    local en = malloc(4)
    write32(en, 1)
    for attempt = 1, 6 do
        local fd = create_socket(AF_INET, 1, 0)
        if fd < 0 then
            ulog(name .. " socket failed attempt=" .. tostring(attempt))
            brief_sleep_ms(200)
        else
            syscall.setsockopt(fd, 0xFFFF, 0x0004, en, 4) -- SO_REUSEADDR
            pcall(function() syscall.setsockopt(fd, 0xFFFF, 0x0200, en, 4) end) -- SO_REUSEPORT
            local ba = make_sockaddr_in(port)
            local ret = syscall.bind(fd, ba, 16)
            ulog(name .. " fd=" .. tostring(fd) .. " bind=" .. tostring(ret)
                 .. " port=" .. tostring(port) .. " try=" .. tostring(attempt))
            -- treat negative / large unsigned as error (port still busy from previous run)
            local failed = (type(ret) == "number" and (ret < 0 or ret > 0x7fffffff))
            if not failed then
                syscall.listen(fd, 128)
                return fd
            end
            pcall(function() syscall.close(fd) end)
            ulog(name .. " bind FAILED try=" .. tostring(attempt))
            brief_sleep_ms(250 * attempt)
        end
    end
    ulog(name .. " bind gave up")
    return -1
end

local ftp_srv = open_listen(1337, "ftp_srv")
local ftp_data = open_listen(1338, "ftp_data")

sc = sc:gsub("%s", "")
local bin = hex_to_binary(sc)
local JIT_SIZE = 0x10000
local bfd = jit_malloc(8)
local rwfd = jit_malloc(8)
local rxfd = jit_malloc(8)
local rwa = jit_malloc(8)  
local rxa = malloc(8)       
local nm = jit_malloc(8)
jit_write_buffer(nm, "nv4b")
jit_sceKernelJitCreateSharedMemory(nm, JIT_SIZE, 7, bfd)
jit_sceKernelJitCreateAliasOfSharedMemory(jit_read32(bfd), PROT_READ|PROT_WRITE, rwfd)
jit_sceKernelJitCreateAliasOfSharedMemory(jit_read32(bfd), PROT_READ|PROT_EXECUTE, rxfd)
jit_sceKernelJitMapSharedMemory(jit_read32(rwfd), PROT_READ|PROT_WRITE, rwa)
local rw = jit_read64(rwa)
local mfd = jit_send_recv_fd(jit_read32(rxfd), NEW_JIT_SOCK, NEW_MAIN_SOCK)
sceKernelJitMapSharedMemory(mfd, PROT_READ|PROT_EXECUTE, rxa)
local rx = read64(rxa)
write_shellcode(rw, sc)
ulog("Code: " .. #bin .. " bytes")

-- ext_args layout 
--   +0x00  s64 status       
--   +0x08  s64 step         
--   +0x10  u32 frame_count
--   +0x18  s32 log_fd
--   +0x1C  s32 pad_fd      
--   +0x20  u8  log_addr[16] (sockaddr_in for UDP log target)
--   +0x30  u64 dbg[0]       (unused)
--   +0x38  u64 dbg[1]       (unused)
--   +0x40  u64 dbg[2]       (unused)
--   +0x48  u64 dbg[3]       userId
--   +0x50  u64 dbg[4]       FTP control fd (port 1337)
--   +0x58  u64 dbg[5]       FTP data fd (port 1338)
local ext = malloc(0x80)
memset(ext, 0, 0x80)
write64(ext+0x00, 0xDEAD)
write32(ext+0x18, log_sock)
write32(ext+0x1C, -1)
for i=0,15 do write8(ext+0x20+i, read8(log_sa+i)) end
write64(ext+0x30, -1)
write64(ext+0x38, 0)
write64(ext+0x40, 0)
write64(ext+0x48, userId)
write64(ext+0x50, ftp_srv >= 0 and ftp_srv or -1)
write64(ext+0x58, ftp_data >= 0 and ftp_data or -1)
local current_ip = get_current_ip()
ulog("IP: " .. current_ip)
send_notification("pNES5\n" .. current_ip)

func_wrap(rx)(EBOOT_BASE, SCE_KERNEL_DLSYM, ext)

local frames = read32(ext+0x10)
ulog("Done! frames=" .. frames)
send_notification("pNES5 done " .. frames .. "f")

-- Always release Lua-owned sockets so the next inject can bind 1337/1338.
-- (With the create_socket JIT-FD fix above, close() fully frees the port.)
local function safe_close(fd, name)
    if fd and type(fd) == "number" and fd >= 0 then
        local ok, err = pcall(function()
            -- Prefer plain close; do not shutdown() listen sockets (can leave odd state).
            syscall.close(fd)
        end)
        ulog((name or "fd") .. " close " .. tostring(fd) .. (ok and " ok" or (" fail:" .. tostring(err))))
    end
end
safe_close(ftp_srv, "ftp_srv")
safe_close(ftp_data, "ftp_data")
safe_close(log_sock, "log")
ulog("Sockets cleaned up")
